docs/infra.md:136:`MainWorker` serves the API (the `@surveybeat/api` declaration over the Organization Durable Object) and the static assets built from `apps/web`; the landing page is `SiteWorker` (ADR 0020), and the answer page's submission path is `SubmissionWorker`. The wiring lives in `WorkerWiring.ts` so its rules are testable, and `WorkerWiring.test.ts` pins them:
docs/infra.md:141:- **Origins.** `APP_ORIGIN` is bound only when the stage has a custom hostname, since the Organization Durable Object builds email links from it. A stage on workers.dev leaves it unset and falls back to a reserved `.invalid` origin; those stages never send real email (see Email above).
docs/infra.md:154:`SiteWorker` serves the prerendered landing page from `apps/web/dist-site` (ADR 0020) with `htmlHandling: "auto-trailing-slash"`. `/app` and `/app/` answer a 302 to the app origin on a GET, and anything the assets do not match answers 404. Production serves the apex only while `APEX_SERVED_BY_SITE` is on, with `www` redirecting to it; staging and PR stages get `<stage>.surveybeat.app`. `EmailConfig.test.ts` pins the redirect rule and both asset directories.
import type { ReactNode } from "react";
import { Body, Container, Head, Hr, Html, Preview, Section, Text } from "react-email";
import type { Messages } from "./messages/index.ts";
import { colors, darkColors, fonts, radius } from "./theme.ts";

const d = darkColors;

const darkMode = `
:root { color-scheme: light dark; supported-color-schemes: light dark; }
@media (prefers-color-scheme: dark) {
  .sb-page { background-color: ${d.page} !important; }
  .sb-card { background-color: ${d.card} !important; border-color: ${d.border} !important; }
  .sb-text { color: ${d.text} !important; }
  .sb-muted { color: ${d.muted} !important; }
  .sb-rule { border-color: ${d.rowBorder} !important; }
  .sb-button { background-color: ${d.button} !important; color: ${d.buttonText} !important; }
  .sb-link { color: ${d.link} !important; }
  .sb-panel { background-color: ${d.panel} !important; }
  .sb-panel-text { color: ${d.panelText} !important; }
  .sb-rating { border-color: ${d.ratingBorder} !important; color: ${d.ratingText} !important; }
}
`;

export function Layout({
  messages,
  preview,
  reason,
  children,
  outside,
}: {
  messages: Messages;
  preview: string;
  reason: string;
  children: ReactNode;

  outside?: ReactNode;
}) {
  return (
    <Html lang={messages.locale}>
      <Head>
        <meta name="color-scheme" content="light dark" />
        <meta name="supported-color-schemes" content="light dark" />
        <style>{darkMode}</style>
      </Head>
      <Preview>{preview}</Preview>
      <Body
        className="sb-page"
        dir="ltr"
        lang={messages.locale}
        style={{ backgroundColor: colors.page, fontFamily: fonts.sans, margin: 0, padding: "40px 0" }}
      >
        <Container style={{ maxWidth: "560px", padding: "0 20px" }}>
          <Text
            className="sb-muted"
            style={{ color: colors.muted, fontSize: "15px", fontWeight: 600, margin: "0 0 16px 8px" }}
          >
            {messages.message("layout.brand")}
          </Text>
          <Section
            className="sb-card"
            style={{
              backgroundColor: colors.card,
              border: `1px solid ${colors.border}`,
              borderRadius: radius.card,
              padding: "40px 36px",
            }}
          >
            {children}
          </Section>
          {outside}
          <Hr
            className="sb-rule"
            style={{ borderTop: `1px solid ${colors.border}`, margin: "24px 0 12px" }}
          />
          <Text
            className="sb-muted"
            style={{ color: colors.muted, fontSize: "12px", lineHeight: "18px", margin: 0 }}
          >
            {reason}
          </Text>
          <Text
            className="sb-muted"
            style={{ color: colors.muted, fontSize: "12px", lineHeight: "18px", margin: "4px 0 0" }}
          >
            {messages.message("layout.signature")}
          </Text>
        </Container>
      </Body>
    </Html>
  );
}

export const textLayout = (messages: Messages, body: readonly string[], reason: string): string =>
  [...body, "", "--", reason, messages.message("layout.signature"), ""].join("\n");
