              : h.a([h.Href(crumb.href), h.Class(linkClass)], [crumb.label]);

          return h.li(
            [h.Class("flex items-center gap-x-2")],
            [
              ...(index === 0
                ? []
                : [h.span([h.AriaHidden(true), h.Class("text-line")], [message("breadcrumb.separator")])]),
              label,
            ],
          );
        }),
      ),
    ],
  );

