    "Cloudflare",
    "OpenRouter",
    "google-vertex/europe",
    "amazon-bedrock/eu-west-1",
    "sb_edit_",
    "sb_answers_",
    "Clear my answers on this device",
    "edpb.europa.eu",
  ])("discloses %s", (needle) => {
    expect(text).toContain(needle);
  });

